//! JSON encoding and decoding for e7 values.
//!
//! The compiler validates `@derive(Serialize, Deserialize)` declarations (structs
//! and enums) and embeds a compact schema string in the generated bytecode.  The
//! same schema builder handles any statically known e7 type at a `json::encode` /
//! `json::decode::<T>` call site, so the runtime helpers only ever see a schema
//! plus the normal aggregate representation:
//!
//!   * struct: pointer to `n` i64 slots (one per field, declaration order)
//!   * enum:   pointer to `1 + payloads` i64 slots: tag, then payload slot(s)
//!   * vector: aggregate `[rows, columns=0, elements...]`, `e7_vec_*`
//!   * matrix: aggregate `[rows, columns, row-major elements...]`, `e7_vec_*`
//!   * map:    aggregate `[length, capacity, entries*]` of (key, value) slots
//!   * str:    aggregate `[len, bytes...]`, accessed through `e7_str_*`
//!   * bool/int: i64 slot value; float: f64 bit pattern in an i64 slot
//!   * optional: one i64 slot; `0` is null (see limitations below)
//!
//! Schema grammar (compiler-generated, acyclic):
//!
//!   type    := 'b' | 'i' | 'f' | 's'
//!            | '[' type ']'                    dynamic vector
//!            | 'A' count ':' type              fixed-size array
//!            | 'M' rows ':' columns ':' type   matrix
//!            | '?' type                        optional
//!            | '<' type ',' type '>'           map
//!            | '{' fields '}'                  struct
//!            | 'E' '{' variants '}'            enum
//!   fields  := field (';' field)* | empty
//!   field   := name '=' type
//!   variants:= variant (';' variant)* | empty
//!   variant := name '=' ('u' | '(' type (',' type)* ')')
//!
//! Wire format:
//!
//!   * bool -> `true` / `false`
//!   * integers -> JSON integers (fraction and exponent forms are rejected)
//!   * floats -> shortest round-trip decimal; `NaN`/`Inf` are rejected
//!   * str -> JSON string; UTF-8 is validated on encode, control characters,
//!     quote and backslash are escaped, and `\uXXXX` escapes (including valid
//!     surrogate pairs) are decoded
//!   * vector -> JSON array
//!   * fixed array -> JSON array; the length must equal the static length
//!   * matrix -> array of row arrays, row-major; dimensions must match the type
//!   * optional -> `null` for `nil`, otherwise the wrapped value
//!   * map -> JSON object; keys are stringified by key type (`str` verbatim,
//!     integer decimal, float decimal, bool `true`/`false`, unit enum variant
//!     name).  Duplicate keys keep the last value.
//!   * struct -> JSON object; field order is free, unknown fields are skipped,
//!     duplicate fields keep the last value, missing optional fields decode as
//!     `nil`, and any other missing field makes the decode fail
//!   * enum -> tagged representation: a unit variant is the JSON string
//!     `"Variant"`; a variant with one unnamed payload is `{"Variant": value}`;
//!     a variant with several unnamed payloads is `{"Variant": [v1, ...]}`
//!
//! Failure policy: both entry points return `0` on malformed input, unsupported
//! values (non-finite floats, non-UTF-8 strings, mismatched fixed dimensions),
//! or out-of-memory.  `0` is also the representation of `false`, integer `0`,
//! and `nil`, so callers that need to distinguish failure should decode into a
//! struct/enum/vector/string (a handle) and compare it with `0`.
//!
//! Ownership: decoded aggregates and strings are malloc-owned for the process
//! lifetime; the runtime has no aggregate free path, matching the rest of the
//! e7 aggregate ABI.  Recursive `@derive` types are rejected by the compiler.

const std = @import("std");
const abi = @import("ffi/abi.zig");
const aggregate = @import("aggregate.zig");

pub const Symbol = abi.Symbol;

const allocator = std.heap.c_allocator;

pub const Error = error{
    InvalidSchema,
    InvalidJson,
    Unsupported,
    OutOfMemory,
};

// --------------------------------------------------------------- layout -----

fn slotPointer(handle: i64) [*]i64 {
    return @ptrFromInt(@as(usize, @intCast(handle)));
}

const VecShape = struct {
    rows: i64,
    columns: i64,
};

/// Read the vector/matrix header directly; `aggregate.zig` documents the
/// `[rows, columns, elements...]` layout and exposes no column getter.
fn vecShape(handle: i64) VecShape {
    if (handle == 0) return .{ .rows = 0, .columns = 0 };
    const slots = slotPointer(handle);
    return .{ .rows = @max(slots[0], 0), .columns = @max(slots[1], 0) };
}

fn stringBytes(handle: i64) ?[]const u8 {
    if (handle == 0) return &.{};
    const length = aggregate.e7_str_len(handle);
    if (length < 0) return null;
    if (length == 0) return &.{};
    const bytes: [*]const u8 = @ptrFromInt(@as(usize, @intCast(handle + 8)));
    return bytes[0..@intCast(length)];
}

fn newString(bytes: []const u8) i64 {
    const data: i64 = if (bytes.len == 0) 0 else @intCast(@intFromPtr(bytes.ptr));
    return aggregate.e7_str_new(data, @intCast(bytes.len));
}

// ---------------------------------------------------------------- schema -----

const Field = struct {
    name: []const u8,
    ty: *Node,
};

const Fixed = struct {
    count: usize,
    element: *Node,
};

const Matrix = struct {
    rows: usize,
    columns: usize,
    element: *Node,
};

const MapType = struct {
    key: *Node,
    value: *Node,
};

const Variant = struct {
    name: []const u8,
    tag: usize,
    payloads: []*Node,
};

const Node = union(enum) {
    bool_,
    int,
    float,
    string,
    vector: *Node,
    fixed: Fixed,
    matrix: Matrix,
    optional: *Node,
    map: MapType,
    struct_: []Field,
    enum_: []Variant,
};

fn findField(fields: []const Field, name: []const u8) ?usize {
    for (fields, 0..) |field, index| {
        if (std.mem.eql(u8, field.name, name)) return index;
    }
    return null;
}

fn findVariant(variants: []const Variant, name: []const u8) ?*const Variant {
    for (variants) |*variant| {
        if (std.mem.eql(u8, variant.name, name)) return variant;
    }
    return null;
}

const max_schema_depth = 64;
const max_container_entries = 1_000_000;

const SchemaParser = struct {
    text: []const u8,
    pos: usize = 0,
    arena: std.mem.Allocator,
    depth: usize = 0,

    fn parse(arena: std.mem.Allocator, text: []const u8) Error!*Node {
        var parser = SchemaParser{ .text = text, .arena = arena };
        const node = try parser.parseNode();
        if (parser.pos != text.len) return error.InvalidSchema;
        return node;
    }

    fn peek(self: *const SchemaParser) ?u8 {
        if (self.pos >= self.text.len) return null;
        return self.text[self.pos];
    }

    fn advance(self: *SchemaParser) ?u8 {
        if (self.pos >= self.text.len) return null;
        const ch = self.text[self.pos];
        self.pos += 1;
        return ch;
    }

    fn expect(self: *SchemaParser, wanted: u8) Error!void {
        const ch = self.advance() orelse return error.InvalidSchema;
        if (ch != wanted) return error.InvalidSchema;
    }

    fn make(self: *SchemaParser, value: Node) Error!*Node {
        const node = self.arena.create(Node) catch return error.OutOfMemory;
        node.* = value;
        return node;
    }

    fn digits(self: *SchemaParser) Error!usize {
        const start = self.pos;
        var value: usize = 0;
        while (self.pos < self.text.len) : (self.pos += 1) {
            const ch = self.text[self.pos];
            if (ch < '0' or ch > '9') break;
            value = value * 10 + (ch - '0');
            if (value > max_container_entries) return error.InvalidSchema;
        }
        if (self.pos == start) return error.InvalidSchema;
        return value;
    }

    /// Read a field/variant name up to (but not including) its terminator.
    fn nameUntil(self: *SchemaParser, terminator: u8) Error![]const u8 {
        const start = self.pos;
        while (self.pos < self.text.len) : (self.pos += 1) {
            const ch = self.text[self.pos];
            if (ch == terminator) break;
            switch (ch) {
                '=', ';', '}', '(', ')', ',', ':', '[', ']' => return error.InvalidSchema,
                else => {},
            }
        }
        if (self.pos == start) return error.InvalidSchema;
        return self.text[start..self.pos];
    }

    fn parseFields(self: *SchemaParser) Error![]Field {
        var fields = std.ArrayList(Field).empty;
        while (true) {
            if (self.peek() == '}') break;
            if (fields.items.len > 0) try self.expect(';');
            const name = try self.nameUntil('=');
            try self.expect('=');
            const ty = try self.parseNode();
            fields.append(self.arena, .{ .name = name, .ty = ty }) catch return error.OutOfMemory;
        }
        try self.expect('}');
        return fields.toOwnedSlice(self.arena) catch return error.OutOfMemory;
    }

    fn parsePayloads(self: *SchemaParser) Error![]*Node {
        var payloads = std.ArrayList(*Node).empty;
        try self.expect('(');
        while (true) {
            if (self.peek() == ')') break;
            if (payloads.items.len > 0) try self.expect(',');
            const payload = try self.parseNode();
            payloads.append(self.arena, payload) catch return error.OutOfMemory;
        }
        try self.expect(')');
        return payloads.toOwnedSlice(self.arena) catch return error.OutOfMemory;
    }

    fn parseVariants(self: *SchemaParser) Error![]Variant {
        var variants = std.ArrayList(Variant).empty;
        while (true) {
            if (self.peek() == '}') break;
            if (variants.items.len > 0) try self.expect(';');
            const name = try self.nameUntil('=');
            try self.expect('=');
            const payloads = if (self.peek() == 'u') blk: {
                _ = self.advance();
                break :blk try self.arena.alloc(*Node, 0);
            } else try self.parsePayloads();
            variants.append(self.arena, .{
                .name = name,
                .tag = variants.items.len,
                .payloads = payloads,
            }) catch return error.OutOfMemory;
        }
        try self.expect('}');
        return variants.toOwnedSlice(self.arena) catch return error.OutOfMemory;
    }

    fn parseNode(self: *SchemaParser) Error!*Node {
        if (self.depth >= max_schema_depth) return error.InvalidSchema;
        self.depth += 1;
        defer self.depth -= 1;

        const tag = self.advance() orelse return error.InvalidSchema;
        switch (tag) {
            'b' => return self.make(.bool_),
            'i' => return self.make(.int),
            'f' => return self.make(.float),
            's' => return self.make(.string),
            '[' => {
                const element = try self.parseNode();
                try self.expect(']');
                return self.make(.{ .vector = element });
            },
            'A' => {
                const count = try self.digits();
                try self.expect(':');
                const element = try self.parseNode();
                return self.make(.{ .fixed = .{ .count = count, .element = element } });
            },
            'M' => {
                const rows = try self.digits();
                try self.expect(':');
                const columns = try self.digits();
                try self.expect(':');
                const element = try self.parseNode();
                return self.make(.{ .matrix = .{ .rows = rows, .columns = columns, .element = element } });
            },
            '?' => {
                const child = try self.parseNode();
                return self.make(.{ .optional = child });
            },
            '<' => {
                const key = try self.parseNode();
                try self.expect(',');
                const value = try self.parseNode();
                try self.expect('>');
                return self.make(.{ .map = .{ .key = key, .value = value } });
            },
            '{' => {
                const fields = try self.parseFields();
                return self.make(.{ .struct_ = fields });
            },
            'E' => {
                try self.expect('{');
                const variants = try self.parseVariants();
                return self.make(.{ .enum_ = variants });
            },
            else => return error.InvalidSchema,
        }
    }
};

// -------------------------------------------------------------- encoding -----

fn emitSlice(out: *std.ArrayList(u8), bytes: []const u8) Error!void {
    out.appendSlice(allocator, bytes) catch return error.OutOfMemory;
}

fn emitByte(out: *std.ArrayList(u8), byte: u8) Error!void {
    out.append(allocator, byte) catch return error.OutOfMemory;
}

fn emitFormatted(out: *std.ArrayList(u8), comptime format: []const u8, value: anytype) Error!void {
    const text = std.fmt.allocPrint(allocator, format, .{value}) catch return error.OutOfMemory;
    defer allocator.free(text);
    try emitSlice(out, text);
}

fn appendJsonString(out: *std.ArrayList(u8), bytes: []const u8) Error!void {
    if (!std.unicode.utf8ValidateSlice(bytes)) return error.Unsupported;
    try emitByte(out, '"');
    for (bytes) |byte| {
        switch (byte) {
            '"' => try emitSlice(out, "\\\""),
            '\\' => try emitSlice(out, "\\\\"),
            '\n' => try emitSlice(out, "\\n"),
            '\r' => try emitSlice(out, "\\r"),
            '\t' => try emitSlice(out, "\\t"),
            0x08 => try emitSlice(out, "\\b"),
            0x0c => try emitSlice(out, "\\f"),
            else => {
                if (byte < 0x20) {
                    try emitFormatted(out, "\\u{x:0>4}", byte);
                } else {
                    try emitByte(out, byte);
                }
            },
        }
    }
    try emitByte(out, '"');
}

fn emitFloat(out: *std.ArrayList(u8), value: i64) Error!void {
    const number: f64 = @bitCast(value);
    if (!std.math.isFinite(number)) return error.Unsupported;
    try emitFormatted(out, "{d}", number);
}

fn mapKeyText(out: *std.ArrayList(u8), key_type: *const Node, key: i64) Error!void {
    switch (key_type.*) {
        .string => {
            const bytes = stringBytes(key) orelse return error.InvalidJson;
            try appendJsonString(out, bytes);
        },
        .int => try emitFormatted(out, "\"{d}\"", key),
        .float => {
            try emitByte(out, '"');
            try emitFloat(out, key);
            try emitByte(out, '"');
        },
        .bool_ => try emitSlice(out, if (key != 0) "\"true\"" else "\"false\""),
        .enum_ => |variants| {
            const tag: usize = @intCast(@max(aggregate.e7_load_i64(key), 0));
            if (tag >= variants.len) return error.Unsupported;
            if (variants[tag].payloads.len != 0) return error.Unsupported;
            try appendJsonString(out, variants[tag].name);
        },
        else => return error.Unsupported,
    }
}

fn encodeNode(out: *std.ArrayList(u8), node: *const Node, value: i64) Error!void {
    switch (node.*) {
        .bool_ => try emitSlice(out, if (value != 0) "true" else "false"),
        .int => try emitFormatted(out, "{d}", value),
        .float => try emitFloat(out, value),
        .string => {
            const bytes = stringBytes(value) orelse return error.InvalidJson;
            try appendJsonString(out, bytes);
        },
        .vector => |element| {
            const count = @max(aggregate.e7_vec_len(value), 0);
            try emitByte(out, '[');
            var index: i64 = 0;
            while (index < count) : (index += 1) {
                if (index > 0) try emitByte(out, ',');
                try encodeNode(out, element, aggregate.e7_vec_get(value, index));
            }
            try emitByte(out, ']');
        },
        .fixed => |fixed| {
            const shape = vecShape(value);
            if (shape.columns != 0 or shape.rows != @as(i64, @intCast(fixed.count))) return error.Unsupported;
            try emitByte(out, '[');
            var index: i64 = 0;
            while (index < shape.rows) : (index += 1) {
                if (index > 0) try emitByte(out, ',');
                try encodeNode(out, fixed.element, aggregate.e7_vec_get(value, index));
            }
            try emitByte(out, ']');
        },
        .matrix => |matrix| {
            const shape = vecShape(value);
            if (shape.rows != @as(i64, @intCast(matrix.rows)) or shape.columns != @as(i64, @intCast(matrix.columns))) {
                return error.Unsupported;
            }
            try emitByte(out, '[');
            var row: i64 = 0;
            while (row < shape.rows) : (row += 1) {
                if (row > 0) try emitByte(out, ',');
                try emitByte(out, '[');
                var column: i64 = 0;
                while (column < shape.columns) : (column += 1) {
                    if (column > 0) try emitByte(out, ',');
                    try encodeNode(out, matrix.element, aggregate.e7_vec_get2(value, row, column));
                }
                try emitByte(out, ']');
            }
            try emitByte(out, ']');
        },
        .optional => |child| {
            if (value == 0) {
                try emitSlice(out, "null");
            } else {
                try encodeNode(out, child, value);
            }
        },
        .map => |map| {
            const count = @max(aggregate.e7_map_len(value), 0);
            try emitByte(out, '{');
            var index: i64 = 0;
            while (index < count) : (index += 1) {
                if (index > 0) try emitByte(out, ',');
                try mapKeyText(out, map.key, aggregate.e7_map_key_at(value, index));
                try emitByte(out, ':');
                try encodeNode(out, map.value, aggregate.e7_map_value_at(value, index));
            }
            try emitByte(out, '}');
        },
        .struct_ => |fields| {
            if (value == 0 and fields.len != 0) return error.Unsupported;
            try emitByte(out, '{');
            for (fields, 0..) |field, index| {
                if (index > 0) try emitByte(out, ',');
                try appendJsonString(out, field.name);
                try emitByte(out, ':');
                try encodeNode(out, field.ty, aggregate.e7_load_i64(value + @as(i64, @intCast(index * 8))));
            }
            try emitByte(out, '}');
        },
        .enum_ => |variants| {
            if (value == 0) return error.Unsupported;
            const tag: usize = @intCast(@max(aggregate.e7_load_i64(value), 0));
            if (tag >= variants.len) return error.Unsupported;
            const variant = variants[tag];
            switch (variant.payloads.len) {
                0 => try appendJsonString(out, variant.name),
                1 => {
                    try emitByte(out, '{');
                    try appendJsonString(out, variant.name);
                    try emitByte(out, ':');
                    try encodeNode(out, variant.payloads[0], aggregate.e7_load_i64(value + 8));
                    try emitByte(out, '}');
                },
                else => {
                    try emitByte(out, '{');
                    try appendJsonString(out, variant.name);
                    try emitByte(out, ':');
                    try emitByte(out, '[');
                    for (variant.payloads, 0..) |payload, index| {
                        if (index > 0) try emitByte(out, ',');
                        try encodeNode(out, payload, aggregate.e7_load_i64(value + @as(i64, @intCast((index + 1) * 8))));
                    }
                    try emitByte(out, ']');
                    try emitByte(out, '}');
                },
            }
        },
    }
}

// -------------------------------------------------------------- decoding -----

const JsonCursor = struct {
    text: []const u8,
    pos: usize = 0,
    depth: usize = 0,

    const max_depth = 256;

    fn skipWhitespace(self: *JsonCursor) void {
        while (self.pos < self.text.len) : (self.pos += 1) {
            switch (self.text[self.pos]) {
                ' ', '\t', '\n', '\r' => {},
                else => return,
            }
        }
    }

    fn peek(self: *JsonCursor) ?u8 {
        self.skipWhitespace();
        if (self.pos >= self.text.len) return null;
        return self.text[self.pos];
    }

    fn advance(self: *JsonCursor) ?u8 {
        self.skipWhitespace();
        if (self.pos >= self.text.len) return null;
        const ch = self.text[self.pos];
        self.pos += 1;
        return ch;
    }

    fn expect(self: *JsonCursor, wanted: u8) Error!void {
        const ch = self.advance() orelse return error.InvalidJson;
        if (ch != wanted) return error.InvalidJson;
    }

    fn expectKeyword(self: *JsonCursor, keyword: []const u8) Error!void {
        self.skipWhitespace();
        if (self.pos + keyword.len > self.text.len) return error.InvalidJson;
        if (!std.mem.eql(u8, self.text[self.pos..][0..keyword.len], keyword)) return error.InvalidJson;
        self.pos += keyword.len;
    }

    fn readHex4(self: *JsonCursor) Error!u21 {
        var code: u21 = 0;
        for (0..4) |_| {
            if (self.pos >= self.text.len) return error.InvalidJson;
            const digit = self.text[self.pos];
            self.pos += 1;
            const value = std.fmt.charToDigit(digit, 16) catch return error.InvalidJson;
            code = code * 16 + value;
        }
        return code;
    }

    fn readString(self: *JsonCursor) Error![]u8 {
        var result = std.ArrayList(u8).empty;
        errdefer result.deinit(allocator);
        try self.expect('"');
        while (true) {
            if (self.pos >= self.text.len) return error.InvalidJson;
            const ch = self.text[self.pos];
            self.pos += 1;
            switch (ch) {
                '"' => return result.toOwnedSlice(allocator) catch error.OutOfMemory,
                '\\' => {
                    if (self.pos >= self.text.len) return error.InvalidJson;
                    const escaped = self.text[self.pos];
                    self.pos += 1;
                    switch (escaped) {
                        '"' => result.append(allocator, '"') catch return error.OutOfMemory,
                        '\\' => result.append(allocator, '\\') catch return error.OutOfMemory,
                        '/' => result.append(allocator, '/') catch return error.OutOfMemory,
                        'b' => result.append(allocator, 0x08) catch return error.OutOfMemory,
                        'f' => result.append(allocator, 0x0c) catch return error.OutOfMemory,
                        'n' => result.append(allocator, '\n') catch return error.OutOfMemory,
                        'r' => result.append(allocator, '\r') catch return error.OutOfMemory,
                        't' => result.append(allocator, '\t') catch return error.OutOfMemory,
                        'u' => {
                            var code = try self.readHex4();
                            if (code >= 0xD800 and code <= 0xDBFF) {
                                // High surrogate: a low surrogate escape must follow.
                                if (self.pos + 1 >= self.text.len or self.text[self.pos] != '\\' or self.text[self.pos + 1] != 'u') {
                                    return error.InvalidJson;
                                }
                                self.pos += 2;
                                const low = try self.readHex4();
                                if (low < 0xDC00 or low > 0xDFFF) return error.InvalidJson;
                                code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                            } else if (code >= 0xDC00 and code <= 0xDFFF) {
                                return error.InvalidJson;
                            }
                            var buffer: [4]u8 = undefined;
                            const encoded = std.unicode.utf8Encode(code, &buffer) catch return error.InvalidJson;
                            result.appendSlice(allocator, buffer[0..encoded]) catch return error.OutOfMemory;
                        },
                        else => return error.InvalidJson,
                    }
                },
                else => {
                    if (ch < 0x20) return error.InvalidJson;
                    result.append(allocator, ch) catch return error.OutOfMemory;
                },
            }
        }
    }

    /// Strict JSON number grammar: `-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?`.
    fn readNumberToken(self: *JsonCursor) Error![]const u8 {
        self.skipWhitespace();
        const start = self.pos;
        if (self.pos < self.text.len and self.text[self.pos] == '-') self.pos += 1;
        if (self.pos >= self.text.len) return error.InvalidJson;
        switch (self.text[self.pos]) {
            '0' => self.pos += 1,
            '1'...'9' => {
                while (self.pos < self.text.len and self.text[self.pos] >= '0' and self.text[self.pos] <= '9') self.pos += 1;
            },
            else => return error.InvalidJson,
        }
        if (self.pos < self.text.len and self.text[self.pos] == '.') {
            self.pos += 1;
            const fraction_start = self.pos;
            while (self.pos < self.text.len and self.text[self.pos] >= '0' and self.text[self.pos] <= '9') self.pos += 1;
            if (self.pos == fraction_start) return error.InvalidJson;
        }
        if (self.pos < self.text.len and (self.text[self.pos] == 'e' or self.text[self.pos] == 'E')) {
            self.pos += 1;
            if (self.pos < self.text.len and (self.text[self.pos] == '+' or self.text[self.pos] == '-')) self.pos += 1;
            const exponent_start = self.pos;
            while (self.pos < self.text.len and self.text[self.pos] >= '0' and self.text[self.pos] <= '9') self.pos += 1;
            if (self.pos == exponent_start) return error.InvalidJson;
        }
        return self.text[start..self.pos];
    }

    fn skipValue(self: *JsonCursor) Error!void {
        if (self.depth >= max_depth) return error.InvalidJson;
        self.depth += 1;
        defer self.depth -= 1;

        const ch = self.peek() orelse return error.InvalidJson;
        switch (ch) {
            '"' => {
                const bytes = try self.readString();
                allocator.free(bytes);
            },
            '{' => {
                _ = self.advance();
                if (self.peek() == '}') {
                    _ = self.advance();
                    return;
                }
                while (true) {
                    const key = try self.readString();
                    allocator.free(key);
                    try self.expect(':');
                    try self.skipValue();
                    const next = self.peek() orelse return error.InvalidJson;
                    _ = self.advance();
                    if (next == '}') return;
                    if (next != ',') return error.InvalidJson;
                }
            },
            '[' => {
                _ = self.advance();
                if (self.peek() == ']') {
                    _ = self.advance();
                    return;
                }
                while (true) {
                    try self.skipValue();
                    const next = self.peek() orelse return error.InvalidJson;
                    _ = self.advance();
                    if (next == ']') return;
                    if (next != ',') return error.InvalidJson;
                }
            },
            't' => try self.expectKeyword("true"),
            'f' => try self.expectKeyword("false"),
            'n' => try self.expectKeyword("null"),
            '-', '0'...'9' => _ = try self.readNumberToken(),
            else => return error.InvalidJson,
        }
    }
};

fn decodeKey(key_type: *const Node, bytes: []const u8) Error!i64 {
    switch (key_type.*) {
        .string => return newString(bytes),
        .int => return std.fmt.parseInt(i64, bytes, 10) catch error.InvalidJson,
        .float => {
            const number = std.fmt.parseFloat(f64, bytes) catch return error.InvalidJson;
            if (!std.math.isFinite(number)) return error.InvalidJson;
            return @bitCast(number);
        },
        .bool_ => {
            if (std.mem.eql(u8, bytes, "true")) return 1;
            if (std.mem.eql(u8, bytes, "false")) return 0;
            return error.InvalidJson;
        },
        .enum_ => |variants| {
            const variant = findVariant(variants, bytes) orelse return error.InvalidJson;
            if (variant.payloads.len != 0) return error.InvalidJson;
            return @intCast(variant.tag);
        },
        else => return error.Unsupported,
    }
}

fn decodeArray(cursor: *JsonCursor, element: *const Node, expected: ?usize) Error!i64 {
    var items = std.ArrayList(i64).empty;
    defer items.deinit(allocator);
    try cursor.expect('[');
    if (cursor.peek() == ']') {
        _ = cursor.advance();
    } else {
        while (true) {
            const value = try decodeNode(cursor, element);
            items.append(allocator, value) catch return error.OutOfMemory;
            const next = cursor.peek() orelse return error.InvalidJson;
            _ = cursor.advance();
            if (next == ']') break;
            if (next != ',') return error.InvalidJson;
        }
    }
    if (expected) |count| {
        if (items.items.len != count) return error.InvalidJson;
    }
    const vector = aggregate.e7_vec_new(@intCast(items.items.len), 0);
    if (vector == 0 and items.items.len != 0) return error.OutOfMemory;
    for (items.items, 0..) |value, index| {
        aggregate.e7_vec_set(vector, @intCast(index), value);
    }
    return vector;
}

fn decodeMatrix(cursor: *JsonCursor, matrix: Matrix) Error!i64 {
    const rows: usize = matrix.rows;
    const columns: usize = matrix.columns;
    const total = std.math.mul(usize, rows, columns) catch return error.InvalidJson;
    if (total > max_container_entries) return error.InvalidJson;
    const vector = aggregate.e7_vec_new(@intCast(rows), @intCast(columns));
    if (vector == 0 and total != 0) return error.OutOfMemory;
    try cursor.expect('[');
    if (cursor.peek() == ']') {
        if (rows != 0) return error.InvalidJson;
        _ = cursor.advance();
        return vector;
    }
    var row: usize = 0;
    while (true) {
        try cursor.expect('[');
        var column: usize = 0;
        if (cursor.peek() == ']') {
            if (columns != 0) return error.InvalidJson;
            _ = cursor.advance();
        } else {
            while (true) {
                if (column >= columns) return error.InvalidJson;
                const value = try decodeNode(cursor, matrix.element);
                aggregate.e7_vec_set2(vector, @intCast(row), @intCast(column), value);
                column += 1;
                const next = cursor.peek() orelse return error.InvalidJson;
                _ = cursor.advance();
                if (next == ']') break;
                if (next != ',') return error.InvalidJson;
            }
        }
        if (column != columns) return error.InvalidJson;
        row += 1;
        const next = cursor.peek() orelse return error.InvalidJson;
        _ = cursor.advance();
        if (next == ']') break;
        if (next != ',') return error.InvalidJson;
    }
    if (row != rows) return error.InvalidJson;
    return vector;
}

fn decodeStruct(cursor: *JsonCursor, fields: []const Field) Error!i64 {
    const value = aggregate.e7_alloc_i64(@intCast(@max(fields.len, 1)));
    if (value == 0) return error.OutOfMemory;
    const seen = allocator.alloc(bool, fields.len) catch return error.OutOfMemory;
    defer allocator.free(seen);
    @memset(seen, false);

    try cursor.expect('{');
    if (cursor.peek() == '}') {
        _ = cursor.advance();
    } else {
        while (true) {
            const key = try cursor.readString();
            defer allocator.free(key);
            try cursor.expect(':');
            if (findField(fields, key)) |index| {
                seen[index] = true;
                const decoded = try decodeNode(cursor, fields[index].ty);
                aggregate.e7_store_i64(value + @as(i64, @intCast(index * 8)), decoded);
            } else {
                try cursor.skipValue();
            }
            const next = cursor.peek() orelse return error.InvalidJson;
            _ = cursor.advance();
            if (next == '}') break;
            if (next != ',') return error.InvalidJson;
        }
    }
    for (fields, 0..) |field, index| {
        if (seen[index]) continue;
        switch (field.ty.*) {
            .optional => aggregate.e7_store_i64(value + @as(i64, @intCast(index * 8)), 0),
            else => return error.InvalidJson,
        }
    }
    return value;
}

fn decodeEnum(cursor: *JsonCursor, variants: []const Variant) Error!i64 {
    const first = cursor.peek() orelse return error.InvalidJson;
    if (first == '"') {
        const name = try cursor.readString();
        defer allocator.free(name);
        const variant = findVariant(variants, name) orelse return error.InvalidJson;
        if (variant.payloads.len != 0) return error.InvalidJson;
        const value = aggregate.e7_alloc_i64(1);
        if (value == 0) return error.OutOfMemory;
        aggregate.e7_store_i64(value, @intCast(variant.tag));
        return value;
    }

    try cursor.expect('{');
    const name = try cursor.readString();
    defer allocator.free(name);
    const variant = findVariant(variants, name) orelse return error.InvalidJson;
    if (variant.payloads.len == 0) return error.InvalidJson;
    try cursor.expect(':');

    var payload_values = std.ArrayList(i64).empty;
    defer payload_values.deinit(allocator);
    if (variant.payloads.len == 1) {
        const decoded = try decodeNode(cursor, variant.payloads[0]);
        payload_values.append(allocator, decoded) catch return error.OutOfMemory;
    } else {
        try cursor.expect('[');
        for (variant.payloads, 0..) |payload, index| {
            if (index > 0) try cursor.expect(',');
            const decoded = try decodeNode(cursor, payload);
            payload_values.append(allocator, decoded) catch return error.OutOfMemory;
        }
        try cursor.expect(']');
    }
    try cursor.expect('}');

    const value = aggregate.e7_alloc_i64(@intCast(payload_values.items.len + 1));
    if (value == 0) return error.OutOfMemory;
    aggregate.e7_store_i64(value, @intCast(variant.tag));
    for (payload_values.items, 0..) |payload, index| {
        aggregate.e7_store_i64(value + @as(i64, @intCast((index + 1) * 8)), payload);
    }
    return value;
}

fn decodeNode(cursor: *JsonCursor, node: *const Node) Error!i64 {
    if (cursor.depth >= JsonCursor.max_depth) return error.InvalidJson;
    cursor.depth += 1;
    defer cursor.depth -= 1;

    switch (node.*) {
        .bool_ => {
            if (cursor.peek() == 't') {
                try cursor.expectKeyword("true");
                return 1;
            }
            try cursor.expectKeyword("false");
            return 0;
        },
        .int => {
            const token = try cursor.readNumberToken();
            if (std.mem.indexOfAny(u8, token, ".eE") != null) return error.InvalidJson;
            return std.fmt.parseInt(i64, token, 10) catch error.InvalidJson;
        },
        .float => {
            const token = try cursor.readNumberToken();
            const number = std.fmt.parseFloat(f64, token) catch return error.InvalidJson;
            if (!std.math.isFinite(number)) return error.InvalidJson;
            return @bitCast(number);
        },
        .string => {
            const bytes = try cursor.readString();
            defer allocator.free(bytes);
            return newString(bytes);
        },
        .vector => |element| return decodeArray(cursor, element, null),
        .fixed => |fixed| return decodeArray(cursor, fixed.element, fixed.count),
        .matrix => |matrix| return decodeMatrix(cursor, matrix),
        .optional => |child| {
            if (cursor.peek() == 'n') {
                try cursor.expectKeyword("null");
                return 0;
            }
            return decodeNode(cursor, child);
        },
        .map => |map| {
            const value = aggregate.e7_map_new();
            if (value == 0) return error.OutOfMemory;
            try cursor.expect('{');
            if (cursor.peek() == '}') {
                _ = cursor.advance();
                return value;
            }
            while (true) {
                const key_bytes = try cursor.readString();
                defer allocator.free(key_bytes);
                const key = try decodeKey(map.key, key_bytes);
                try cursor.expect(':');
                const decoded = try decodeNode(cursor, map.value);
                // String-keyed maps use content equality so duplicate wire keys
                // overwrite instead of appending; other keys compare by value.
                if (map.key.* == .string) {
                    aggregate.e7_map_set_str(value, key, decoded);
                } else {
                    aggregate.e7_map_set(value, key, decoded);
                }
                const next = cursor.peek() orelse return error.InvalidJson;
                _ = cursor.advance();
                if (next == '}') break;
                if (next != ',') return error.InvalidJson;
            }
            return value;
        },
        .struct_ => |fields| return decodeStruct(cursor, fields),
        .enum_ => |variants| return decodeEnum(cursor, variants),
    }
}

// --------------------------------------------------------------- entry -------

fn schemaNode(arena: *std.heap.ArenaAllocator, schema: i64) Error!*Node {
    const bytes = stringBytes(schema) orelse return error.InvalidSchema;
    if (bytes.len == 0) return error.InvalidSchema;
    return SchemaParser.parse(arena.allocator(), bytes);
}

/// `schema` and `value` are e7 handles; the result is an e7 `str` handle, or 0
/// when the value does not match the schema.
pub export fn e7_json_encode(schema: i64, value: i64) callconv(.c) i64 {
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const node = schemaNode(&arena, schema) catch return 0;
    var out = std.ArrayList(u8).empty;
    defer out.deinit(allocator);
    encodeNode(&out, node, value) catch return 0;
    return newString(out.items);
}

/// `schema` and `text` are e7 handles; the result is the decoded value handle,
/// or 0 on malformed JSON / schema mismatch.
pub export fn e7_json_decode(schema: i64, text: i64) callconv(.c) i64 {
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const node = schemaNode(&arena, schema) catch return 0;
    const text_bytes = stringBytes(text) orelse return 0;
    // JSON text is UTF-8 by definition; reject invalid byte sequences up front
    // so raw string bodies cannot smuggle non-UTF-8 bytes into e7 strings.
    if (!std.unicode.utf8ValidateSlice(text_bytes)) return 0;
    var cursor = JsonCursor{ .text = text_bytes };
    const value = decodeNode(&cursor, node) catch return 0;
    cursor.skipWhitespace();
    if (cursor.pos != text_bytes.len) return 0;
    return value;
}

pub fn symbols() [2]Symbol {
    return .{
        .{ .name = "e7_json_encode", .address = @intFromPtr(&e7_json_encode) },
        .{ .name = "e7_json_decode", .address = @intFromPtr(&e7_json_decode) },
    };
}

test "json encode/decode round-trips escaped strings" {
    const schema = newString("{name=s}");
    const value = aggregate.e7_alloc_i64(1);
    const name = newString("a\"b\nc");
    aggregate.e7_store_i64(value, name);

    const encoded = e7_json_encode(schema, value);
    try std.testing.expect(encoded != 0);
    const encoded_bytes = stringBytes(encoded).?;
    try std.testing.expectEqualStrings("{\"name\":\"a\\\"b\\nc\"}", encoded_bytes);

    const decoded = e7_json_decode(schema, encoded);
    try std.testing.expect(decoded != 0);
    const decoded_name = aggregate.e7_load_i64(decoded);
    try std.testing.expectEqualStrings("a\"b\nc", stringBytes(decoded_name).?);
}

// --------------------------------------------------------------- testing -----

fn encodeForTest(schema_text: []const u8, value: i64) ![]const u8 {
    const schema = newString(schema_text);
    const encoded = e7_json_encode(schema, value);
    try std.testing.expect(encoded != 0);
    return stringBytes(encoded).?;
}

fn decodeForTest(schema_text: []const u8, text: []const u8) i64 {
    const schema = newString(schema_text);
    const json = newString(text);
    return e7_json_decode(schema, json);
}

fn expectDecodeFails(schema_text: []const u8, text: []const u8) !void {
    try std.testing.expectEqual(@as(i64, 0), decodeForTest(schema_text, text));
}

fn makeStruct(count: usize) i64 {
    return aggregate.e7_alloc_i64(@intCast(@max(count, 1)));
}

test "json round-trips booleans and integers" {
    const true_bits: i64 = 1;
    try std.testing.expectEqualStrings("true", try encodeForTest("b", true_bits));
    try std.testing.expectEqualStrings("false", try encodeForTest("b", 0));
    try std.testing.expectEqual(@as(i64, 1), decodeForTest("b", "true"));
    try std.testing.expectEqual(@as(i64, 0), decodeForTest("b", "false"));

    try std.testing.expectEqualStrings("42", try encodeForTest("i", 42));
    try std.testing.expectEqualStrings("-7", try encodeForTest("i", -7));
    try std.testing.expectEqualStrings("0", try encodeForTest("i", 0));
    try std.testing.expectEqual(@as(i64, 42), decodeForTest("i", "42"));
    try std.testing.expectEqual(@as(i64, -7), decodeForTest("i", " -7 "));
    try std.testing.expectEqual(@as(i64, std.math.maxInt(i64)), decodeForTest("i", "9223372036854775807"));
}

test "json rejects malformed numbers and keywords" {
    try expectDecodeFails("i", "4.2");
    try expectDecodeFails("i", "1e2");
    try expectDecodeFails("i", "+1");
    try expectDecodeFails("i", "01");
    try expectDecodeFails("i", "--1");
    try expectDecodeFails("i", "1.");
    try expectDecodeFails("i", ".5");
    try expectDecodeFails("i", "9223372036854775808");
    try expectDecodeFails("i", "true");
    try expectDecodeFails("i", "");
    try expectDecodeFails("b", "True");
    try expectDecodeFails("b", "1");
    try expectDecodeFails("b", "tru");
    try expectDecodeFails("f", "nan");
    try expectDecodeFails("f", "inf");
    try expectDecodeFails("f", "1e999");
}

test "json encodes and decodes floats" {
    const one_half: i64 = @bitCast(@as(f64, 1.5));
    try std.testing.expectEqualStrings("1.5", try encodeForTest("f", one_half));
    try std.testing.expectEqual(@as(f64, 1.5), @as(f64, @bitCast(decodeForTest("f", "1.5"))));
    try std.testing.expectEqual(@as(f64, 100.0), @as(f64, @bitCast(decodeForTest("f", "1e2"))));
    const neg_zero: i64 = @bitCast(@as(f64, -0.0));
    const encoded = try encodeForTest("f", neg_zero);
    const round = @as(f64, @bitCast(decodeForTest("f", encoded)));
    try std.testing.expectEqual(@as(f64, -0.0), round);
    const nan: i64 = @bitCast(std.math.nan(f64));
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString("f"), nan));
    const inf: i64 = @bitCast(std.math.inf(f64));
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString("f"), inf));
}

test "json strings escape control characters and decode unicode escapes" {
    const value = newString("a\"b\\c\nd\te");
    try std.testing.expectEqualStrings(
        "\"a\\\"b\\\\c\\nd\\te\"",
        try encodeForTest("s", value),
    );

    const unicode = newString("h\u{00e9}llo \u{1f600}");
    const encoded = try encodeForTest("s", unicode);
    try std.testing.expectEqualStrings("\"h\u{00e9}llo \u{1f600}\"", encoded);

    const escaped = decodeForTest("s", "\"h\\u00e9llo \\uD83D\\uDE00\"");
    try std.testing.expect(escaped != 0);
    try std.testing.expectEqualStrings("h\u{00e9}llo \u{1f600}", stringBytes(escaped).?);

    try expectDecodeFails("s", "\"unterminated");
    try expectDecodeFails("s", "\"\\q\"");
    try expectDecodeFails("s", "\"\\uD800\"");
    try expectDecodeFails("s", "\"\\uDC00\"");
    try expectDecodeFails("s", "\"a\nb\"");
    try expectDecodeFails("s", "\"a\"x");
    try expectDecodeFails("s", "\"\xff\"");

    var invalid_utf8 = [_]u8{ 'x', 0xff };
    const bad = newString(&invalid_utf8);
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString("s"), bad));
}

test "json structs skip unknown fields and require non-optional fields" {
    const schema = "{a=i;b=s;c=?i}";
    const value = makeStruct(3);
    aggregate.e7_store_i64(value, 5);
    aggregate.e7_store_i64(value + 8, newString("x"));
    aggregate.e7_store_i64(value + 16, 0);
    try std.testing.expectEqualStrings("{\"a\":5,\"b\":\"x\",\"c\":null}", try encodeForTest(schema, value));

    const decoded = decodeForTest(schema, "{\"c\":null,\"extra\":[1,{\"k\":true}],\"b\":\"y\",\"a\":3}");
    try std.testing.expect(decoded != 0);
    try std.testing.expectEqual(@as(i64, 3), aggregate.e7_load_i64(decoded));
    try std.testing.expectEqualStrings("y", stringBytes(aggregate.e7_load_i64(decoded + 8)).?);
    try std.testing.expectEqual(@as(i64, 0), aggregate.e7_load_i64(decoded + 16));

    const missing_optional = decodeForTest(schema, "{\"a\":1,\"b\":\"z\"}");
    try std.testing.expect(missing_optional != 0);
    try std.testing.expectEqual(@as(i64, 0), aggregate.e7_load_i64(missing_optional + 16));

    try expectDecodeFails(schema, "{\"a\":1}");
    try expectDecodeFails(schema, "{\"a\":1,\"b\":\"z\",}");
    try expectDecodeFails(schema, "{\"a\":\"wrong\",\"b\":\"z\"}");

    const duplicated = decodeForTest(schema, "{\"a\":1,\"a\":2,\"b\":\"z\"}");
    try std.testing.expect(duplicated != 0);
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_load_i64(duplicated));
}

test "json vectors, fixed arrays, and matrices" {
    const vector = aggregate.e7_vec_new(3, 0);
    aggregate.e7_vec_set(vector, 0, 1);
    aggregate.e7_vec_set(vector, 1, 2);
    aggregate.e7_vec_set(vector, 2, 3);
    try std.testing.expectEqualStrings("[1,2,3]", try encodeForTest("[i]", vector));

    const decoded_vector = decodeForTest("[i]", " [1, 2, 3] ");
    try std.testing.expect(decoded_vector != 0);
    try std.testing.expectEqual(@as(i64, 3), aggregate.e7_vec_len(decoded_vector));
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_vec_get(decoded_vector, 1));
    try expectDecodeFails("[i]", "[1,]");
    try expectDecodeFails("[i]", "[1 2]");
    try expectDecodeFails("[i]", "[1]x");

    const fixed = aggregate.e7_vec_new(2, 0);
    aggregate.e7_vec_set(fixed, 0, 7);
    aggregate.e7_vec_set(fixed, 1, 8);
    try std.testing.expectEqualStrings("[7,8]", try encodeForTest("A2:i", fixed));
    const decoded_fixed = decodeForTest("A2:i", "[7,8]");
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_vec_len(decoded_fixed));
    try expectDecodeFails("A2:i", "[7]");
    try expectDecodeFails("A2:i", "[7,8,9]");
    const wrong_fixed = aggregate.e7_vec_new(3, 0);
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString("A2:i"), wrong_fixed));

    const matrix = aggregate.e7_vec_new(2, 2);
    aggregate.e7_vec_set2(matrix, 0, 0, 1);
    aggregate.e7_vec_set2(matrix, 0, 1, 2);
    aggregate.e7_vec_set2(matrix, 1, 0, 3);
    aggregate.e7_vec_set2(matrix, 1, 1, 4);
    try std.testing.expectEqualStrings("[[1,2],[3,4]]", try encodeForTest("M2:2:i", matrix));
    const decoded_matrix = decodeForTest("M2:2:i", "[[1,2],[3,4]]");
    const shape = vecShape(decoded_matrix);
    try std.testing.expectEqual(@as(i64, 2), shape.rows);
    try std.testing.expectEqual(@as(i64, 2), shape.columns);
    try std.testing.expectEqual(@as(i64, 4), aggregate.e7_vec_get2(decoded_matrix, 1, 1));
    try expectDecodeFails("M2:2:i", "[[1,2],[3]]");
    try expectDecodeFails("M2:2:i", "[[1,2]]");
    try expectDecodeFails("M2:2:i", "[[1,2],[3,4],[5,6]]");
    const wrong_matrix = aggregate.e7_vec_new(1, 4);
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString("M2:2:i"), wrong_matrix));
}

test "json maps stringify keys and decode back" {
    const map = aggregate.e7_map_new();
    aggregate.e7_map_set_str(map, newString("a"), 1);
    aggregate.e7_map_set_str(map, newString("bb"), 2);
    try std.testing.expectEqualStrings("{\"a\":1,\"bb\":2}", try encodeForTest("<s,i>", map));

    const decoded = decodeForTest("<s,i>", "{\"bb\":2,\"a\":1}");
    try std.testing.expect(decoded != 0);
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_map_len(decoded));
    try std.testing.expectEqual(@as(i64, 1), aggregate.e7_map_get_str(decoded, newString("a")));
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_map_get_str(decoded, newString("bb")));
    try expectDecodeFails("<s,i>", "{\"a\":}");
    const duplicated = decodeForTest("<s,i>", "{\"a\":1,\"a\":2}");
    try std.testing.expectEqual(@as(i64, 1), aggregate.e7_map_len(duplicated));
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_map_get_str(duplicated, newString("a")));

    const int_map = aggregate.e7_map_new();
    aggregate.e7_map_set(int_map, 7, newString("seven"));
    aggregate.e7_map_set(int_map, 9, newString("nine"));
    try std.testing.expectEqualStrings("{\"7\":\"seven\",\"9\":\"nine\"}", try encodeForTest("<i,s>", int_map));
    const decoded_int_map = decodeForTest("<i,s>", "{\"9\":\"nine\",\"7\":\"seven\"}");
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_map_len(decoded_int_map));
    try std.testing.expectEqualStrings("seven", stringBytes(aggregate.e7_map_get(decoded_int_map, 7)).?);
    try expectDecodeFails("<i,s>", "{\"seven\":\"x\"}");

    const bool_map = aggregate.e7_map_new();
    aggregate.e7_map_set(bool_map, 1, 10);
    try std.testing.expectEqualStrings("{\"true\":10}", try encodeForTest("<b,i>", bool_map));
}

test "json enums use the tagged representation" {
    const unit = makeStruct(1);
    aggregate.e7_store_i64(unit, 0);
    try std.testing.expectEqualStrings("\"Red\"", try encodeForTest("E{Red=u;Rgb=(i,i,i)}", unit));

    const payload = makeStruct(4);
    aggregate.e7_store_i64(payload, 1);
    aggregate.e7_store_i64(payload + 8, 1);
    aggregate.e7_store_i64(payload + 16, 2);
    aggregate.e7_store_i64(payload + 24, 3);
    try std.testing.expectEqualStrings("{\"Rgb\":[1,2,3]}", try encodeForTest("E{Red=u;Rgb=(i,i,i)}", payload));

    const decoded_unit = decodeForTest("E{Red=u;Rgb=(i,i,i)}", "\"Red\"");
    try std.testing.expect(decoded_unit != 0);
    try std.testing.expectEqual(@as(i64, 0), aggregate.e7_load_i64(decoded_unit));

    const decoded_payload = decodeForTest("E{Red=u;Rgb=(i,i,i)}", "{\"Rgb\":[1,2,3]}");
    try std.testing.expect(decoded_payload != 0);
    try std.testing.expectEqual(@as(i64, 1), aggregate.e7_load_i64(decoded_payload));
    try std.testing.expectEqual(@as(i64, 2), aggregate.e7_load_i64(decoded_payload + 16));

    try expectDecodeFails("E{Red=u;Rgb=(i,i,i)}", "\"Rgb\"");
    try expectDecodeFails("E{Red=u;Rgb=(i,i,i)}", "{\"Red\":null}");
    try expectDecodeFails("E{Red=u;Rgb=(i,i,i)}", "{\"Rgb\":[1,2]}");
    try expectDecodeFails("E{Red=u;Rgb=(i,i,i)}", "{\"Nope\":1}");
    const single = decodeForTest("E{Only=(i)}", "{\"Only\":1}");
    try std.testing.expect(single != 0);
    try std.testing.expectEqual(@as(i64, 1), aggregate.e7_load_i64(single + 8));
}

test "json optionals encode null and present values" {
    try std.testing.expectEqualStrings("null", try encodeForTest("?s", 0));
    try std.testing.expectEqualStrings("\"x\"", try encodeForTest("?s", newString("x")));
    try std.testing.expectEqual(@as(i64, 0), decodeForTest("?s", "null"));
    const present = decodeForTest("?s", "\"x\"");
    try std.testing.expect(present != 0);
    try std.testing.expectEqualStrings("x", stringBytes(present).?);
    try expectDecodeFails("?s", "0");
}

test "json handles empty aggregates" {
    try std.testing.expectEqualStrings("{}", try encodeForTest("{}", 0));
    try std.testing.expectEqualStrings("[]", try encodeForTest("[i]", 0));
    try std.testing.expectEqualStrings("{}", try encodeForTest("<s,i>", 0));
    const empty_struct = decodeForTest("{}", "{}");
    try std.testing.expect(empty_struct != 0);
    const empty_vector = decodeForTest("[i]", "[]");
    try std.testing.expect(empty_vector != 0);
    try std.testing.expectEqual(@as(i64, 0), aggregate.e7_vec_len(empty_vector));
    const empty_map = decodeForTest("<s,i>", "{}");
    try std.testing.expect(empty_map != 0);
    try std.testing.expectEqual(@as(i64, 0), aggregate.e7_map_len(empty_map));
}

test "json rejects invalid schemas" {
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString(""), 0));
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString("Q"), 0));
    try std.testing.expectEqual(@as(i64, 0), e7_json_encode(newString("{a=i"), 0));
    try std.testing.expectEqual(@as(i64, 0), e7_json_decode(newString("E{"), newString("null")));
}
